using MediStock.Data;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;
namespace MediStock.Pages.Invoices;
[Authorize]public sealed class DetailsModel(MediStockDbContext db):PageModel{public Sale?Sale{get;private set;}public IReadOnlyList<InvoiceItem>Items{get;private set;}=[];public string PharmacyName{get;private set;}="MediStock Pharmacy";public string PharmacyAddress{get;private set;}="";
public async Task<IActionResult>OnGetAsync(int id,CancellationToken ct){Sale=await db.Sales.AsNoTracking().Include(x=>x.Items).ThenInclude(x=>x.Medicine).Include(x=>x.Items).ThenInclude(x=>x.StockBatch).SingleOrDefaultAsync(x=>x.Id==id,ct);if(Sale is null)return NotFound();Items=Sale.Items.Select(x=>new InvoiceItem(x.Medicine.Name,x.StockBatch.BatchNumber,x.Quantity,x.UnitPrice,x.LineTotal)).ToList();using var conn=db.Database.GetDbConnection();await conn.OpenAsync(ct);await using var cmd=conn.CreateCommand();cmd.CommandText="SELECT Key, Value FROM AppSettings";await using var reader=await cmd.ExecuteReaderAsync(ct);while(await reader.ReadAsync(ct)){var key=reader.GetString(0);if(key=="PharmacyName")PharmacyName=reader.GetString(1);if(key=="PharmacyAddress")PharmacyAddress=reader.GetString(1);}return Page();}
public async Task<IActionResult>OnPostVoidAsync(int id,string reason,CancellationToken ct){if(!User.IsInRole("Administrator"))return Forbid();var sale=await db.Sales.Include(x=>x.Items).SingleOrDefaultAsync(x=>x.Id==id,ct);if(sale is null||sale.Status!="Completed")return NotFound();await using var tx=await db.Database.BeginTransactionAsync(ct);foreach(var item in sale.Items){var batch=await db.StockBatches.SingleAsync(x=>x.Id==item.StockBatchId,ct);batch.Quantity+=item.Quantity;}sale.Status="Voided";sale.VoidReason=reason.Trim();sale.RefundedAtUtc=DateTime.UtcNow;await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);TempData["StatusMessage"]="Sale voided and stock restored.";return RedirectToPage("/Sales/Index");}
}
public sealed record InvoiceItem(string Medicine,string Batch,int Quantity,decimal UnitPrice,decimal LineTotal);
